{
  "nl": {
    "issue": [
      {
        "text": "运输合同如何界定，从事公共运输的承运人是否负有强制缔约义务",
        "rules": ["c809", "c810"]
      },
      {
        "text": "旅客违反客票义务的后果，以及实名制客运合同旅客丢失客票的处理",
        "rules": ["c815-1a", "c815-1b", "c815-refuse", "c815-2"]
      },
      {
        "text": "承运人的安全运输义务、按客票运输义务，以及迟延运输等不能正常运输情形下的义务与赔偿责任",
        "rules": ["c819-1", "c819-2", "c820-1", "c820-2", "c820-3"]
      },
      {
        "text": "旅客随身携带物品与托运行李毁损、灭失时承运人的责任",
        "rules": ["c824-1", "c824-2"]
      },
      {
        "text": "托运人的手续提交、包装义务与任意变更解除权，以及承运人的留置权与提存权",
        "rules": ["c826", "c827-1", "c827-pack", "c827-2", "c829", "c836", "c837"]
      },
      {
        "text": "运输过程中货物毁损、灭失的赔偿责任与免责事由，以及因不可抗力灭失时的运费风险",
        "rules": ["c832-1", "c832-exempt", "c835-1", "c835-2", "c835-other"]
      },
      {
        "text": "多式联运经营人的全程责任、单据签发、托运人过错责任与区段责任的法律适用",
        "rules": ["c838-whole", "c839-internal", "c839-whole", "c840", "c840-type", "c841", "c842-segment", "c842-chapter"]
      }
    ],
    "conditions": [
      {
        "text": "承运人将旅客或者货物从起运地点运输到约定地点，旅客、托运人或者收货人支付票款或者运输费用",
        "rules": ["c809"]
      },
      {
        "text": "承运人从事公共运输，旅客、托运人提出通常、合理的运输要求",
        "rules": ["c810"]
      },
      {
        "text": "旅客持有效客票；或者无票乘坐、超程乘坐、越级乘坐、持不符合减价条件的优惠客票乘坐",
        "rules": ["c815-1a", "c815-1b"]
      },
      {
        "text": "旅客不支付票款",
        "rules": ["c815-refuse"]
      },
      {
        "text": "实名制客运合同的旅客丢失客票",
        "rules": ["c815-2"]
      },
      {
        "text": "承运人迟延运输或者有其他不能正常运输情形，并由此造成旅客损失",
        "rules": ["c820-2", "c820-3"]
      },
      {
        "text": "运输过程中旅客随身携带物品毁损、灭失，且承运人有过错",
        "rules": ["c824-1"]
      },
      {
        "text": "旅客托运的行李毁损、灭失",
        "rules": ["c824-2"]
      },
      {
        "text": "货物运输需要办理审批、检验等手续",
        "rules": ["c826"]
      },
      {
        "text": "当事人就包装方式有约定；或者对包装方式没有约定、约定不明确",
        "rules": ["c827-1", "c827-pack"]
      },
      {
        "text": "承运人尚未将货物交付收货人",
        "rules": ["c829"]
      },
      {
        "text": "运输过程中货物毁损、灭失",
        "rules": ["c832-1", "c832-exempt"]
      },
      {
        "text": "货物在运输过程中因不可抗力灭失，承运人未收取或者已经收取运费",
        "rules": ["c835-1", "c835-2"]
      },
      {
        "text": "法律对因不可抗力灭失货物的运费另有规定",
        "rules": ["c835-other"]
      },
      {
        "text": "托运人或者收货人不支付运费、保管费或者其他费用，且当事人未约定不得留置",
        "rules": ["c836"]
      },
      {
        "text": "收货人不明或者收货人无正当理由拒绝受领货物",
        "rules": ["c837"]
      },
      {
        "text": "多式联运经营人负责履行或者组织履行多式联运合同",
        "rules": ["c838-whole"]
      },
      {
        "text": "多式联运经营人与各区段承运人就各区段运输约定相互之间的责任",
        "rules": ["c839-internal", "c839-whole"]
      },
      {
        "text": "多式联运经营人收到托运人交付的货物，托运人要求签发可转让或者不可转让单据",
        "rules": ["c840", "c840-type"]
      },
      {
        "text": "因托运人托运货物时的过错造成多式联运经营人损失，即使托运人已经转让多式联运单据",
        "rules": ["c841"]
      },
      {
        "text": "货物毁损、灭失发生于多式联运的某一运输区段，或者该区段不能确定",
        "rules": ["c842-segment", "c842-chapter"]
      }
    ],
    "exceptions": [
      {
        "text": "旅客不支付票款的，承运人可以拒绝运输，公共运输承运人的强制缔约义务被排除",
        "rules": ["c815-refuse"]
      },
      {
        "text": "迟延运输等造成旅客损失不可归责于承运人的，承运人不承担赔偿责任",
        "rules": ["c820-3"]
      },
      {
        "text": "承运人证明货物毁损、灭失是因不可抗力、货物本身的自然性质或者合理损耗以及托运人、收货人的过错造成的，不承担赔偿责任",
        "rules": ["c832-exempt", "c832-1"]
      },
      {
        "text": "法律对货物因不可抗力灭失后的运费另有规定的，依照其规定",
        "rules": ["c835-other", "c835-1", "c835-2"]
      },
      {
        "text": "当事人另有约定不得留置的，承运人不享有对相应运输货物的留置权",
        "rules": ["c836"]
      },
      {
        "text": "多式联运经营人与区段承运人的内部责任约定，不影响其对全程运输承担的义务",
        "rules": ["c839-whole", "c839-internal"]
      }
    ],
    "effects": [
      {
        "text": "从事公共运输的承运人不得拒绝旅客、托运人通常、合理的运输要求",
        "rules": ["c810"]
      },
      {
        "text": "旅客应当按照有效客票记载的时间、班次和座位号乘坐；无票、超程、越级或者持不符合减价条件的优惠客票乘坐的，应当补交票款，承运人可以按照规定加收票款",
        "rules": ["c815-1a", "c815-1b"]
      },
      {
        "text": "实名制客运合同的旅客丢失客票的，可以请求承运人挂失补办，承运人不得再次收取票款和其他不合理费用",
        "rules": ["c815-2"]
      },
      {
        "text": "承运人应当严格履行安全运输义务并及时告知安全运输应当注意的事项；旅客对承运人为安全运输所作的合理安排应当积极协助和配合",
        "rules": ["c819-1", "c819-2"]
      },
      {
        "text": "承运人应当按照有效客票记载的时间、班次和座位号运输旅客；迟延运输或者有其他不能正常运输情形的，应当及时告知和提醒旅客、采取必要的安置措施，并根据旅客的要求安排改乘其他班次或者退票；由此造成旅客损失的，应当承担赔偿责任",
        "rules": ["c820-1", "c820-2", "c820-3"]
      },
      {
        "text": "随身携带物品毁损、灭失，承运人有过错的应当承担赔偿责任；托运行李毁损、灭失的，适用货物运输的有关规定",
        "rules": ["c824-1", "c824-2"]
      },
      {
        "text": "托运人应当提交办理完审批、检验等手续的文件，并按照约定的方式包装货物；对包装方式没有约定或者约定不明确的，适用第619条的规定；违反包装义务的，承运人可以拒绝运输",
        "rules": ["c826", "c827-1", "c827-pack", "c827-2"]
      },
      {
        "text": "在货物交付收货人之前，托运人可以要求承运人中止运输、返还货物、变更到达地或者将货物交给其他收货人，但应当赔偿承运人因此受到的损失",
        "rules": ["c829"]
      },
      {
        "text": "承运人对运输过程中货物的毁损、灭失承担赔偿责任",
        "rules": ["c832-1"]
      },
      {
        "text": "货物因不可抗力灭失，未收取运费的承运人不得请求支付运费；已经收取运费的，托运人可以请求返还",
        "rules": ["c835-1", "c835-2"]
      },
      {
        "text": "托运人或者收货人不支付运费、保管费或者其他费用的，承运人对相应的运输货物享有留置权；收货人不明或者无正当理由拒绝受领货物的，承运人可以依法提存货物",
        "rules": ["c836", "c837"]
      },
      {
        "text": "多式联运经营人负责履行或者组织履行多式联运合同，对全程运输享有承运人的权利、承担承运人的义务，并在收到货物时签发多式联运单据（可为可转让或者不可转让单据）",
        "rules": ["c838-whole", "c840", "c840-type"]
      },
      {
        "text": "多式联运经营人与各区段承运人可以约定相互之间的责任，但该约定不影响其对全程运输承担的义务",
        "rules": ["c839-internal", "c839-whole"]
      },
      {
        "text": "因托运人托运货物时的过错造成多式联运经营人损失的，即使托运人已经转让多式联运单据，仍应当承担赔偿责任",
        "rules": ["c841"]
      },
      {
        "text": "货物毁损、灭失发生于可确定区段的，适用调整该区段运输方式的有关法律；区段不能确定的，依照运输合同章的规定承担赔偿责任",
        "rules": ["c842-segment", "c842-chapter"]
      }
    ],
    "priority": [
      {
        "text": "旅客不支付票款时，承运人拒绝运输的权利优先于公共运输承运人的强制缔约义务",
        "rules": ["c815-refuse", "c810"]
      },
      {
        "text": "托运行李毁损、灭失适用货物运输的规定（无过错责任），不适用随身携带物品的过错责任",
        "rules": ["c824-2", "c824-1"]
      },
      {
        "text": "承运人证明存在不可抗力、货物自然性质或者合理损耗、托运人或者收货人过错的，其免责优先于货物毁损、灭失的赔偿责任",
        "rules": ["c832-exempt", "c832-1"]
      },
      {
        "text": "法律对因不可抗力灭失货物的运费另有规定的，优先于第835条第1款的运费规则",
        "rules": ["c835-other", "c835-1", "c835-2"]
      },
      {
        "text": "多式联运经营人对全程运输承担的义务优先于区段承运人之间的内部责任约定",
        "rules": ["c839-whole", "c839-internal", "c838-whole"]
      },
      {
        "text": "毁损、灭失发生于可确定区段的，优先适用调整该区段运输方式的有关法律，而非本章规定",
        "rules": ["c842-segment", "c842-chapter"]
      }
    ],
    "distinguish": [
      {
        "text": "笔记：客运合同自承运人向旅客出具客票时成立，当事人另有约定或者另有交易习惯的除外；该规则在第814条，本行未挂载，故不形式化",
        "rules": []
      },
      {
        "text": "笔记：承运人对旅客人身伤亡承担无过错责任，免责事由为伤亡系旅客自身健康原因造成或者承运人证明系旅客故意、重大过失造成；该规则在第823条，本行未挂载，故不形式化",
        "rules": []
      },
      {
        "text": "笔记：承运人负有尽力救助旅客的义务；该规则在第822条，本行未挂载，故不形式化",
        "rules": []
      },
      {
        "text": "笔记：搭便车属好意施惠，双方无运输合同关系，只能主张侵权责任，且仅在故意、重大过失时不得减轻责任",
        "rules": []
      },
      {
        "text": "笔记：随身携带物品毁损、灭失承运人承担过错责任，托运行李则适用货物运输规定承担无过错责任，二者归责原则不同",
        "rules": ["c824-1", "c824-2"]
      },
      {
        "text": "笔记：货运合同大多为第三人利益合同，收货人可依合同主张相应权利；本行法条未直接规定，故不形式化",
        "rules": []
      },
      {
        "text": "笔记：旅客主张违约可请求精神损害赔偿，但违约与侵权不能并存；本行法条未规定，故不形式化",
        "rules": []
      },
      {
        "text": "笔记：运输合同为双务、有偿、一般诺成、通常为格式合同，承运人一般负强制缔约义务；其中仅强制缔约义务在第810条有明文，其余为学理概括",
        "rules": ["c810"]
      }
    ]
  },
